FLOWS = [("model", "email"),
         ("web", "model"),
         ("student", "model"),
         ("model", "search")]

def at_risk(flows, untrusted, acts):
    reach = set(untrusted)
    for _ in flows:
        for a, b in flows:
            if a in reach:
                reach.add(b)
    found = [c for c in acts if c in reach]
    return sorted(found)

for c in at_risk(FLOWS, {"web"}, {"email"}):
    print("at risk:", c)

