def score(w, b, x):
    s = sum(a * c for a, c in zip(w, x))
    return s + b

def nudge(w, x, eps):
    sign = lambda a: (a > 0) - (a < 0)
    return [c - eps * sign(a)
            for a, c in zip(w, x)]

w, b, x = [2, -1, 1], -1, [1, 1, 1]
print(score(w, b, x))
print(score(w, b, nudge(w, x, 0.5)))

